/**
 * Evaluates thresholds against metric scores.
 * @param {Array} evaluations - Array of evaluated metrics
 * @param {Object} thresholds - Object mapping metric IDs to minimum score thresholds
 * @returns {Object} Result with passed status and threshold details
 */
function evaluateThresholds(evaluations, thresholds) {
  const results = [];
  let allPassed = true;

  for (const [metricId, minScore] of Object.entries(thresholds)) {
    const metric = evaluations.find((m) => m.id === metricId);
    const score = metric?.score;
    const passed = score !== null && score !== undefined && score >= minScore;

    if (!passed) allPassed = false;

    results.push({
      metric: metricId,
      min: minScore,
      score,
      passed
    });
  }

  return { passed: allPassed, thresholds: results };
}

export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  generatedAt = new Date().toISOString(),
  thresholds
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  if (thresholds && Object.keys(thresholds).length > 0) {
    const thresholdResult = evaluateThresholds(evaluations, thresholds);
    report.passed = thresholdResult.passed;
    report.thresholds = thresholdResult.thresholds;
  }

  return report;
}

