    return total;
  }, 0);

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  if (thresholds && Object.keys(thresholds).length > 0) {
    const thresholdResult = evaluateThresholds(evaluations, thresholds);
    report.passed = thresholdResult.passed;
    report.thresholds = thresholdResult.thresholds;
  }

  return report;
}

export function writeReport({
  report,
  format = 'json',
  reportPath,
  fs: fsModule = defaultFs
}) {
  const resolved = resolveReportPath(reportPath, format);
  const payload = format === 'markdown' ? toMarkdown(report) : toJson(report);
  fsModule.writeFileSync(resolved, payload, 'utf8');

